-- Contacts: the people at a client the owner deals with. Each contact belongs to one client
-- (client_id -> clients.id) and carries a name, an email and their role, so the client's page can
-- list its contacts. (`role` is spelled `contact_role` in the table to dodge any SQL keyword.)
CREATE TABLE contacts (
    id           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    client_id    BIGINT NOT NULL REFERENCES clients(id),
    name         VARCHAR(255) NOT NULL,
    email        VARCHAR(255) NOT NULL,
    contact_role VARCHAR(255) NOT NULL
);
-- A contact must have a proper email address, not just a non-null one. Enforce the shape at the DB
-- level too (local part, @, a domain with a dot), matching the server (ContactsPostLogic) +
-- front-end validation: rejects '' and values with no @/domain, so no bad row can slip in through
-- any path.
ALTER TABLE contacts
    ADD CONSTRAINT contacts_email_format CHECK (email LIKE '%_@_%._%');
-- Tasks: a checklist item on a project. Each task belongs to one project (project_id -> projects.id)
-- and is either OPEN (done = FALSE, the default) or DONE (done = TRUE), ticked off as work completes.
CREATE TABLE tasks (
    id         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    project_id BIGINT NOT NULL REFERENCES projects(id),
    title      VARCHAR(255) NOT NULL,
    done       BOOLEAN NOT NULL DEFAULT FALSE
);
-- An invoice is now built from line items: one row per thing being charged for — a description, how
-- many (qty), and the price of each (unit_price). An invoice's amount is the sum of qty * unit_price
-- across its lines, so the figure is worked out, never typed. Each line belongs to one invoice
-- (invoice_id -> invoices.id), so an invoice's detail page lists only its own lines.
CREATE TABLE invoice_line_items (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    invoice_id  BIGINT NOT NULL REFERENCES invoices(id),
    description VARCHAR(255) NOT NULL,
    qty         INTEGER NOT NULL,
    unit_price  NUMERIC(12, 2) NOT NULL
);
-- The invoice amount is now DERIVED: it is the sum of the invoice's line items (Flyway V13), kept
-- in the amount column as a worked-out total rather than a figure typed by hand. An invoice with no
-- lines yet totals zero, so the "amount must be positive" rule (Flyway V6) no longer holds — a draft
-- can exist before anything has been charged to it. Drop that constraint; the total is still
-- recomputed on the server every time a line is added.
ALTER TABLE invoices DROP CONSTRAINT invoices_amount_positive;
-- Archiving a project tucks it away instead of deleting it: it drops off the lists but the row is
-- retained, and a toggle can reveal archived ones again. A new boolean column, defaulting to FALSE
-- so every existing project stays active.
ALTER TABLE projects ADD COLUMN archived BOOLEAN NOT NULL DEFAULT FALSE;
-- Tags and their assignment to projects. A tag is a reusable label (e.g. "urgent", "retainer");
-- project_tags assigns a tag to a project so projects can be grouped by the labels they share. The
-- surrogate id on project_tags keeps the join table a plain IDENTITY row (seeded without an id),
-- while a project is never double-tagged with the same tag (enforced by the app and this unique key).
CREATE TABLE tags (
    id   BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name VARCHAR(255) NOT NULL
);

CREATE TABLE project_tags (
    id         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    project_id BIGINT NOT NULL REFERENCES projects(id),
    tag_id     BIGINT NOT NULL REFERENCES tags(id),
    UNIQUE (project_id, tag_id)
);
-- Notes: a free-text note written against a target (e.g. a project). Each note records what it is
-- about (target_type + target_id), the note text, and when it was written (at). Notes are shown
-- newest first, ordered by `at` descending. `note_text` avoids the reserved word TEXT.
CREATE TABLE notes (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    target_type VARCHAR(32) NOT NULL,
    target_id   BIGINT NOT NULL,
    note_text   VARCHAR(2000) NOT NULL,
    at          TIMESTAMP WITH TIME ZONE NOT NULL
);
-- Archiving a client tucks it away instead of deleting it: it drops off the list and search but the
-- row is retained (nothing is lost). A new boolean column, defaulting to FALSE so every existing
-- client stays active.
ALTER TABLE clients ADD COLUMN archived BOOLEAN NOT NULL DEFAULT FALSE;
-- A payment recorded against an invoice: what a client has paid, and when. One row per payment —
-- an amount and a date — belonging to one invoice (invoice_id -> invoices.id), so an invoice's
-- detail page lists only its own payments.
CREATE TABLE payments (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    invoice_id  BIGINT NOT NULL REFERENCES invoices(id),
    amount      NUMERIC(12, 2) NOT NULL,
    paid_date   DATE NOT NULL
);
-- Clients: the people/organisations the owner works with (name + email).
CREATE TABLE clients (
    id    BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name  VARCHAR(255) NOT NULL,
    email VARCHAR(255) NOT NULL
);
-- How much is still left to pay on an invoice is now shown per row (amount minus its payments), so
-- the project invoice list sums each invoice's payments once per row. Index the column those sums
-- group by (invoice_id, matching the per-invoice payments query). Additive: no data changes.
CREATE INDEX idx_payments_invoice ON payments (invoice_id);
-- A project carries a lifecycle status so its row can show whether it is being worked on, parked,
-- or done: ACTIVE (in progress), ON_HOLD (paused) or FINISHED (completed). New projects default to
-- ACTIVE; existing rows adopt the same default via the column default.
ALTER TABLE projects ADD COLUMN status VARCHAR(16) NOT NULL DEFAULT 'ACTIVE';
-- A project can carry a budget: the figure the owner has agreed to spend on it, against which the
-- amount invoiced so far is measured. A new nullable NUMERIC column — a project without one set
-- simply has no budget yet, so every existing row stays untouched (NULL = no budget).
ALTER TABLE projects ADD COLUMN budget NUMERIC(12, 2);
-- The dashboard measures "overdue" against a fixed reference date rather than the wall clock, so the
-- overdue count is deterministic under test. That reference date ("as of") lives in a single-row
-- app_clock table: the harness seed sets it, and the dashboard's overdue endpoint reads it (falling
-- back to the real current date when none is set). A single row is expected, keyed on id = 1.
CREATE TABLE app_clock (
    id INT PRIMARY KEY,
    as_of DATE NOT NULL
);
-- A client has one main (primary) contact. Flag it on the contact row: at most one contact per
-- client is the main one. Defaults to FALSE so existing contacts are "not the main contact" until
-- one is chosen; the server (ContactsPrimaryLogic) keeps the "one per client" invariant by clearing
-- the others when a new main contact is set. (`primary` is a SQL keyword, so the column is is_primary.)
ALTER TABLE contacts
    ADD COLUMN is_primary BOOLEAN NOT NULL DEFAULT FALSE;
-- Two clients cannot share an email. Enforce uniqueness at the DB level too (the last line of
-- defence), matching the duplicate check in the server (ClientsPostLogic) and the error the front-end
-- surfaces. Applies to every client row regardless of archived state: an email already on file — even
-- an archived one — cannot be reused for a new client.
ALTER TABLE clients
    ADD CONSTRAINT clients_email_unique UNIQUE (email);
-- A charge line now records the unit it is measured in (e.g. "hours", "days", "items") alongside how
-- many (qty) and the price of each (unit_price), so a line reads "2 hours" rather than a bare "2".
-- New lines default to "units"; existing rows adopt the same default via the column default.
ALTER TABLE invoice_line_items ADD COLUMN unit VARCHAR(50) NOT NULL DEFAULT 'units';
-- A client must have a proper email address, not just a non-null one. Enforce the shape at the DB
-- level too (local part, @, a domain with a dot), matching the server + front-end validation:
-- rejects '' and values with no @/domain, so no bad row can slip in through any path.
ALTER TABLE clients
    ADD CONSTRAINT clients_email_format CHECK (email LIKE '%_@_%._%');
-- Projects: a piece of work the owner does for a client. Each project belongs to one client
-- (client_id -> clients.id), so the projects list can show the client's name via the join.
CREATE TABLE projects (
    id        BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name      VARCHAR(255) NOT NULL,
    client_id BIGINT NOT NULL REFERENCES clients(id)
);
-- Invoices: an amount billed on a project. Each invoice belongs to one project
-- (project_id -> projects.id), so a project's detail page lists ITS invoices and totals them.
CREATE TABLE invoices (
    id         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    project_id BIGINT NOT NULL REFERENCES projects(id),
    amount     NUMERIC(12, 2) NOT NULL
);
-- Invoices carry a payment status so a project's detail page can show UNPAID/PAID and mark one paid.
-- New invoices default to UNPAID; existing rows adopt the same default via the column default.
ALTER TABLE invoices ADD COLUMN status VARCHAR(16) NOT NULL DEFAULT 'UNPAID';
-- An invoice must bill a positive amount — you cannot raise an invoice for nothing. Enforce it at
-- the DB level too, matching the server + front-end validation: rejects zero and negative amounts,
-- so no bad row can slip in through any path.
ALTER TABLE invoices
    ADD CONSTRAINT invoices_amount_positive CHECK (amount > 0);
-- Invoices now carry two dates: issued_date (when it went out) and due_date (when payment is due),
-- so a project's detail page can show both on each invoice row. Existing rows adopt today's date as
-- issued and 30 days later as due via the column defaults; new rows set them explicitly on create.
ALTER TABLE invoices ADD COLUMN issued_date DATE NOT NULL DEFAULT CURRENT_DATE;
ALTER TABLE invoices ADD COLUMN due_date DATE NOT NULL DEFAULT DATEADD('DAY', 30, CURRENT_DATE);
-- Sorting a project's invoices by due date is a first-class view now, so index the column the sort
-- orders by (scoped by project, matching the per-project list query). Additive: no data changes.
CREATE INDEX idx_invoices_project_due ON invoices (project_id, due_date);
-- Invoices now move through a lifecycle: DRAFT -> SENT -> PAID. A freshly raised invoice starts as a
-- DRAFT (it is sent later, which is what records an audit entry and unlocks payment), so the column
-- default becomes DRAFT. Existing rows keep whatever status they already hold.
ALTER TABLE invoices ALTER COLUMN status SET DEFAULT 'DRAFT';

